if (!bins) return false;

    T minCost = std::numeric_limits<T>::max();
    int bestAxis = -1;
    T bestCut = 0;

    for (int axis = 0; axis < 3; ++axis) {
        T bmin_axis = bmin[axis];
        T bmax_axis = bmax[axis];
        T range = bmax_axis - bmin_axis;
        if (range <= 0) continue;

        // Precompute surface area of the parent bounding box
        T parentSA = 2.0f * ((bmax[0] - bmin[0]) * (bmax[1] - bmin[1]) +
                             (bmax[1] - bmin[1]) * (bmax[2] - bmin[2]) +
                             (bmax[2] - bmin[2]) * (bmax[0] - bmin[0]));

        // Binning data
        int numBins = bins->numBins;
        std::vector<int> count(numBins, 0);
        std::vector<T> binBmin(numBins, std::numeric_limits<T>::max());
        std::vector<T> binBmax(numBins, -std::numeric_limits<T>::max());

        // Fill bins based on the provided BinBuffer
        for (int i = 0; i < bins->numPrimitives; ++i) {
            int binIdx = bins->getBinIndex(i, axis);
            count[binIdx]++;
            T pMin = bins->getPrimitiveMin(i, axis);
            T pMax = bins->getPrimitiveMax(i, axis);
            binBmin[binIdx] = std::min(binBmin[binIdx], pMin);
            binBmax[binIdx] = std::max(binBmax[binIdx], pMax);
        }

        // Evaluate each possible split plane between bins
        int leftCount = 0;
        T leftMin = std::numeric_limits<T>::max();
        T leftMax = -std::numeric_limits<T>::max();

        for (int i = 0; i < numBins - 1; ++i) {
            leftCount += count[i];
            leftMin = std::min(leftMin, binBmin[i]);
            leftMax = std::max(leftMax, binBmax[i]);

            if (leftCount == 0) continue;

            // Calculate right side bounds and count
            int rightCount = bins->numPrimitives - leftCount;
            if (rightCount == 0) continue;

            T rightMin = std::numeric_limits<T>::max();
            T rightMax = -std::numeric_limits<T>::max();
            for (int j = i + 1; j < numBins; ++j) {
                rightMin = std::min(rightMin, binBmin[j]);
                rightMax = std::max(rightMax, binBmax[j]);
            }

            // SAH Cost: Cost = C_trav + (SA(L)/SA(P) * N(L) * C_isect) + (SA(R)/SA(P) * N(R) * C_isect)
            // We simplify by ignoring constants and using SA * N
            auto calcSA = [&](T minA, T maxA, T minB, T maxB, T minC, T maxC) {
                T da = maxA - minA;
                T db = maxB - minB;
                T dc = maxC - minC;
                return 2.0f * (da * db + db * dc + dc * da);
            };

            T saL = calcSA(axis == 0 ? leftMin : bmin[0], axis == 0 ? leftMax : bmax[0],
                           axis == 1 ? leftMin : bmin[1], axis == 1 ? leftMax : bmax[1],
                           axis == 2 ? leftMin : bmin[2], axis == 2 ? leftMax : bmax[2]);

            T saR = calcSA(axis == 0 ? rightMin : bmin[0], axis == 0 ? rightMax : bmax[0],
                           axis == 1 ? rightMin : bmin[1], axis == 1 ? rightMax : bmax[1],
                           axis == 2 ? rightMin : bmin[2], axis == 2 ? rightMax : bmax[2]);

            T cost = saL * leftCount + saR * rightCount;

            if (cost < minCost) {
                minCost = cost;
                bestAxis = axis;
                bestCut = (bmin_axis + (T(i + 1) / numBins) * range);
            }
        }
    }

    if (bestAxis == -1) return false;

    *minCostAxis = bestAxis;
    cut_pos[bestAxis] = bestCut;
    return true;

